const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // A region of interest over the Omkareshwar Dam reservoir on the Narmada River, a known site for a large floating solar farm.
    const aoi = ee.Geometry.Rectangle([76.13, 22.24, 76.18, 22.27]);

    const date1_start = '2023-02-09';
    const date1_end = '2023-02-11';
    const date2_start = '2025-01-29';
    const date2_end = '2025-01-31';

    // 2. Data Acquisition and Cloud Masking Function
    const getSentinel2Cloudless = function(startDate, endDate, geometry) {
        const collection = ee.ImageCollection("COPERNICUS/S2_SR_HARMONIZED")
            .filterDate(startDate, endDate)
            .filterBounds(geometry);

        const maskClouds = function(image) {
            const qa = image.select('QA60');
            const cloudBitMask = 1 << 10;
            const cirrusBitMask = 1 << 11;
            let mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
            return image.updateMask(mask).divide(10000)
                .select(['B3', 'B8', 'B11']) // Green, NIR, SWIR1
                .copyProperties(image, ["system:time_start"]);
        };

        return collection.map(maskClouds).mosaic().clip(geometry);
    };

    // 3. Processing and Calculation
    const image2023 = getSentinel2Cloudless(date1_start, date1_end, aoi);
    const image2025 = getSentinel2Cloudless(date2_start, date2_end, aoi);

    // Check if images exist. Using a sample to check for valid bands.
    const check2023 = image2023.bandNames().size().getInfo();
    if (check2023 === 0) {
        console.log("No valid cloud-free images found for Feb 2023 period.");
        console.log("C1");
        return;
    }
    const check2025 = image2025.bandNames().size().getInfo();
    if (check2025 === 0) {
        console.log("No valid cloud-free images found for Jan 2025 period.");
        console.log("C1");
        return;
    }

    // Function to identify floating solar panels
    const countSolarPanels = function(image, year) {
        // NDWI to identify water bodies. NDWI = (Green - NIR) / (Green + NIR)
        const ndwi = image.normalizedDifference(['B3', 'B8']).rename('ndwi');
        const waterMask = ndwi.gt(0.1);

        // Panels are dark. A very low NIR reflectance is a good indicator.
        // We also use a low SWIR1 value to differentiate from vegetated/moist soil shorelines.
        const panelMask = image.select('B8').lt(0.05)
                              .and(image.select('B11').lt(0.1));

        // Final mask: pixels that are on water AND are very dark (potential panels)
        const floatingPanels = waterMask.and(panelMask);

        const area = floatingPanels.multiply(ee.Image.pixelArea());
        const stats = area.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: aoi,
            scale: 10,
            maxPixels: 1e9
        });

        const panelArea = ee.Number(stats.get('ndwi')).getInfo(); // Reducer keeps the first band name

        if (panelArea === null || panelArea === undefined) {
            console.log(`Calculation failed for ${year}.`);
            return null;
        }

        const pixelCount = floatingPanels.mask(floatingPanels).reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: aoi,
            scale: 10,
            maxPixels: 1e9
        }).get('ndwi').getInfo();

        if (pixelCount === 0) {
            console.log(`No valid pixels identified as panels for ${year}. Area is 0.`);
            return 0;
        }

        return panelArea;
    };

    // 4. Validation & Final Answer
    const panelArea2023 = countSolarPanels(image2023, 2023);
    const panelArea2025 = countSolarPanels(image2025, 2025);

    if (panelArea2023 === null || panelArea2025 === null) {
        console.log("C3");
        return;
    }

    console.log(`Estimated panel area in Feb 2023 (sq. meters): ${Math.round(panelArea2023)}`);
    console.log(`Estimated panel area in Jan 2025 (sq. meters): ${Math.round(panelArea2025)}`);

    if (panelArea2023 > panelArea2025) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
